import { Spine, AnimationStateListener, TrackEntry, Event } from '@esotericsoftware/spine-pixi-v8';
import { IAnimationOptions, IEventObject, ISkeletonExtended } from './types';

const defaultAnimationOptions: Readonly<IAnimationOptions> = {
    trackIndex: 0,
    loop: false
};

export default class SpineExtended extends Spine {
    public skeleton!: ISkeletonExtended;

    /**
     *  This fuction will set an animation on a spine and resolve once the animation is complete.
     * @param animationName - The name of the animation you would like to play.
     * @param options - TrackIndex, loop, events and listener functions e.g. complete and start
     * @returns Promise<void>
     */
    public setAnimationPromise(animationName: string, options: Partial<IAnimationOptions> = {}): Promise<void> {
        return this.playAnimation(animationName, options, 'Set');
    }

    /**
     * This fuction will add an animation to the spine and resolve once the animation is complete.
     * @param animationName - The name of the animation you would like to play.
     * @param options - TrackIndex, loop, events and listener functions e.g. complete and start
     * @param delay - delay used for the addAnimation function (defaults to 0)
     * @returns Promise<void>
     */
    public addAnimationPromise(animationName: string, options: Partial<IAnimationOptions> = {}, delay: number = 0): Promise<void> {
        return this.playAnimation(animationName, options, 'Add', delay);
    }

    private playAnimation(animationName: string, options: Partial<IAnimationOptions> = {}, setOrAdd: 'Set' | 'Add', delay: number = 0): Promise<void> {
        const combinedOptions = { ...defaultAnimationOptions, ...options };

        return new Promise((resolve) => {
            let trackEntry;
            if (setOrAdd === 'Set') {
                trackEntry = this.state.setAnimation(combinedOptions.trackIndex, animationName, combinedOptions.loop);
            } else {
                trackEntry = this.state.addAnimation(combinedOptions.trackIndex, animationName, combinedOptions.loop, delay);
            }

            const listener: AnimationStateListener = {};

            if (combinedOptions.onEvent) {
                listener.event = (entry: TrackEntry, eventData: Event) => {
                    combinedOptions.onEvent?.forEach((eventObject: IEventObject) => {
                        if (eventData.data.name === eventObject.eventName) {
                            eventObject.eventFunction();
                        }
                    });
                };
            }

            if (combinedOptions.onStart) {
                listener.start = combinedOptions.onStart;
            }

            if (combinedOptions.onInterupt) {
                listener.interrupt = combinedOptions.onInterupt;
            }

            if (combinedOptions.onEnd) {
                listener.end = combinedOptions.onEnd;
            }

            if (combinedOptions.onDispose) {
                listener.dispose = combinedOptions.onDispose;
            }

            listener.complete = () => {
                if (combinedOptions.onComplete) {
                    combinedOptions.onComplete();
                }
                resolve();
            };

            trackEntry.listener = listener;
        });
    }
}
